<script setup lang="ts">
import {computed,onMounted,ref} from 'vue';import {useRouter} from 'vue-router';import {useStudies} from '../stores/studies';import {useSamples} from '../stores/samples';import {useResearch} from '../stores/research';import {useAuth} from '../stores/auth';import {useTask} from '../hooks/useTask';import {directions} from '../constants/enums';import StudySelect from '../components/StudySelect.vue';import ErrorNotice from '../components/common/ErrorNotice.vue';const study=useStudies(),samples=useSamples(),research=useResearch(),auth=useAuth(),router=useRouter(),{error,perform}=useTask(),open=ref(false);onMounted(()=>perform(async()=>{await study.load();await Promise.all([samples.load(),research.loadRuns(),study.loadCriteria()])}));const selected=computed(()=>samples.items.filter(s=>study.current?.material_ids.includes(s.id))),maxPrice=computed(()=>Math.max(50,Math.ceil(Math.max(...selected.value.map(s=>s.price),0)/50)*50));const families=computed(()=>[...new Set(selected.value.map(s=>s.family))]);const color=(family:string)=>['var(--moss)','var(--earth)','var(--clay)'][families.value.indexOf(family)%3];async function create(e:Event){const d=new FormData(e.target as HTMLFormElement);await study.save({...Object.fromEntries(d),material_ids:samples.items.map(s=>s.id)});router.push('/data')}
</script><template><div class="folio-line"><span>研究册 No. 23 / 2026.11</span><span>五种尺度，一份可复核的取舍</span></div><StudySelect/><ErrorNotice :error="error"/><section class="opening"><div class="opening-copy"><p class="eyebrow">MATERIALS, WITH THEIR TRADE-OFFS</p><h1>在声学与成本之间，<br/><em>留下权衡的依据。</em></h1><p class="lead">单项出色，未必面面俱到。<br/>先理解不同偏好如何改变排序，<br/>再决定下一份试样验证什么。</p><div class="study-caption"><b>{{study.current?.name}}</b><p>{{study.current?.context}}</p><small>{{study.current?.source_file}}</small></div><RouterLink class="text-link" to="/data">打开试样与指标口径 ↗</RouterLink></div><figure class="sample-field"><div class="figure-title"><b>试样的声学 / 成本切面</b><small>每个点是一份真实输入记录</small></div><svg viewBox="0 0 540 360" role="img" :aria-label="selected.length+'份试样的单价与吸声系数散点'"><g v-for="a in [0,.25,.5,.75,1]" :key="a"><line x1="50" x2="505" :y1="300-a*240" :y2="300-a*240" stroke="currentColor" opacity=".12"/><text x="40" :y="304-a*240" text-anchor="end" class="axis-text">{{a}}</text></g><g v-for="n in [0,1,2,3,4]" :key="n"><text :x="50+n/4*455" y="324" text-anchor="middle" class="axis-text">{{maxPrice*n/4}}</text></g><text x="50" y="30" class="axis-title">吸声系数 αw ↑</text><text x="505" y="350" text-anchor="end" class="axis-title">单价 元/m² →</text><g v-for="(s,i) in selected" :key="s.id"><circle :cx="50+s.price/maxPrice*455" :cy="300-s.absorption*240" r="5" :fill="color(s.family)" opacity=".8"><title>{{s.code}} {{s.name}}：吸声{{s.absorption}}；单价{{s.price}}</title></circle><text v-if="i%12===0" :x="55+s.price/maxPrice*455" :y="290-s.absorption*240" class="point-label">{{s.code}}</text></g></svg><figcaption><span v-for="f in families" :key="f"><i :style="{background:color(f)}"/>{{f}}</span></figcaption><p class="figure-note">图中仅呈现两项原始量；完整权衡还包括耐冲击、碳强度与厚度。</p></figure></section><section class="index-strip"><div><small>本研究候选</small><strong>{{selected.length}}<i>份试样</i></strong></div><div><small>预先定义指标</small><strong>{{study.criteria.length}}<i>项</i></strong></div><div><small>默认权重情景</small><strong>1,000<i>次</i></strong></div><p>向量标准化TOPSIS<br/>+ Dirichlet偏好权重情景<br/><span>不作统计推断，也不代替试样验证。</span></p></section><section class="research-path"><div><small>01 / 核对</small><h3>先把方向说清楚</h3><p>{{study.criteria.map(c=>c.name+' '+(c.direction==='benefit'?'↑':'↓')).join(' / ')||'请先定义研究指标'}}</p><RouterLink to="/data">核对口径 →</RouterLink></div><div><small>02 / 权衡</small><h3>一组权重，一种偏好</h3><p>保留理想点、距离与每次情景重排，查看名次何时改变。</p><RouterLink to="/runs">配置研究 →</RouterLink></div><div><small>03 / 验证</small><h3>把问题交给试样</h3><p>{{research.runs.filter(r=>r.status==='completed').length}}项完成研究可作为试样提案依据。</p><RouterLink to="/notes">阅读试样计划 →</RouterLink></div></section><section v-if="auth.canEdit" class="registry"><button class="text-link" @click="open=!open">{{open?'收起登记':'＋ 登记另一套权衡研究'}}</button><form v-if="open" class="form-grid" @submit.prevent="e=>perform(()=>create(e))"><label>研究编号<input name="code" pattern="[A-Za-z0-9_-]+" required minLength="2"/></label><label>研究名称<input name="name" required minLength="2"/></label><label>源文件名<input name="source_file"/></label><label>研究背景<textarea name="context"/></label><button class="primary">登记并核对指标 →</button><p class="muted">先纳入当前资料库试样，随后可在核对页调整候选集合与指标。</p></form></section></template>